<script setup lang="ts">
import { ref, computed, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import axios from 'axios';
import { boardApi } from '../../utils/boardApi';
import { imageUrl } from '../../utils/catalog';
import { useUserStore } from '../../utils/userStore';
import BoardWrite from './BoardWrite.vue';
const route=useRoute();const router=useRouter();const userStore=useUserStore();
const labels:Record<string,string>={free:'자유게시판',qna:'Q&A',notice:'공지사항',event:'이벤트'};
const post=ref<any>(null);const loading=ref(true);const error=ref('');const editing=ref(false);const adminVerified=ref(false);const deleting=ref(false);
const canManage=computed(()=>userStore.isLoggedIn.value && (userStore.isAdmin.value ? adminVerified.value : post.value?.author?.userId===userStore.user.value?.userId&&!['notice','event'].includes(post.value?.category)));
const date=(value:string)=>new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
let version=0;
async function fetchPost(){const current=++version;loading.value=true;error.value='';post.value=null;try{const {data}=await boardApi.getPost(String(route.params.id));if(current===version)post.value=data.post;if(userStore.isAdmin.value){try{await axios.get('/api/admin/session');adminVerified.value=true}catch{adminVerified.value=false}}}catch(cause:any){if(current===version)error.value=cause.response?.data?.message||'게시글을 불러오지 못했습니다.'}finally{if(current===version)loading.value=false}}
async function deletePost(){if(deleting.value||!confirm('이 게시글을 삭제할까요? 삭제 후 복구할 수 없습니다.'))return;deleting.value=true;try{await boardApi.deletePost(post.value._id,localStorage.getItem('accessToken')||'');await router.push('/board')}catch(cause:any){error.value=cause.response?.data?.message||'삭제하지 못했습니다.'}finally{deleting.value=false}}
async function saved(){editing.value=false;await fetchPost()}
watch(()=>route.params.id,fetchPost,{immediate:true});
</script>
<template>
 <article class="community-detail"><nav class="detail-breadcrumb" aria-label="현재 위치"><RouterLink to="/board">COMMUNITY</RouterLink><span>/</span><span>{{labels[post?.category]||'이야기'}}</span></nav><div v-if="loading" class="detail-state" role="status">이야기를 불러오고 있습니다.</div><div v-else-if="!post" class="detail-state" role="alert"><span class="detail-error-mark">!</span><h1>이야기를 열 수 없습니다.</h1><p>{{error}}</p><div class="detail-state-actions"><button @click="fetchPost">다시 시도</button><RouterLink to="/board">목록으로 돌아가기 ↗</RouterLink></div></div><template v-else><header class="community-post-header"><span class="post-kicker">부캉이 / {{labels[post.category]}}</span><h1>{{post.title}}</h1><div class="community-post-meta"><span>{{post.author?.name||'탈퇴한 회원'}}</span><time :datetime="post.createdAt">{{date(post.createdAt)}}</time><span>조회 {{post.views}}</span><span v-if="post.isPrivate" class="privacy-label">비밀글</span></div></header><p v-if="error" class="detail-inline-error" role="alert">{{error}}</p><div class="community-post-body"><img v-if="post.imageUrl" :src="imageUrl(post.imageUrl)" alt="게시글 첨부 이미지" loading="lazy" /><p>{{post.content}}</p></div><footer class="post-actions"><RouterLink to="/board" class="back-to-board">← 전체 이야기</RouterLink><div v-if="canManage"><button @click="editing=true">수정</button><button class="delete-post" :disabled="deleting" @click="deletePost">{{deleting?'삭제 중…':'삭제'}}</button></div></footer></template>
 <Teleport to="body"><div v-if="editing" class="detail-modal-backdrop" @click.self="editing=false" @keydown.esc="editing=false"><section class="detail-modal" role="dialog" aria-modal="true" aria-label="게시글 수정"><header><h2>이야기 수정</h2><button aria-label="수정 창 닫기" @click="editing=false">×</button></header><BoardWrite :edit-data="post" @saved="saved" @close="editing=false" /></section></div></Teleport>
 </article>
</template>
<style scoped>
.community-detail{max-width:1040px;margin:auto;padding:52px 5vw 90px;color:#344831}.detail-breadcrumb{display:flex;gap:16px;font-size:13px;letter-spacing:1px;color:#89967c;margin-bottom:55px}.detail-breadcrumb a{text-decoration:none}.community-post-header{padding-bottom:35px;border-bottom:1px solid #d9e1d0}.post-kicker{font-size:14px;color:#7d8c6f;letter-spacing:1px}.community-post-header h1{font-size:32px;line-height:1.6;font-weight:400;letter-spacing:-1.2px;margin:22px 0;overflow-wrap:anywhere}.community-post-meta{display:flex;gap:22px;align-items:center;font-size:14px;color:#97a18a;flex-wrap:wrap}.privacy-label{background:#eef2e7;padding:5px 8px;color:#6f835c}.community-post-body{padding:44px 0 60px;min-height:280px;border-bottom:1px solid #d9e1d0}.community-post-body img{display:block;max-width:100%;max-height:900px;object-fit:contain;margin:0 auto 36px}.community-post-body>p{font-size:18px;color:#58664e;line-height:2.1;white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.post-actions{display:flex;justify-content:space-between;align-items:center;padding-top:24px;gap:15px}.back-to-board{font-size:15px;text-decoration:none;border-bottom:1px solid #526d43;padding:10px 0}.post-actions button,.detail-state button{border:1px solid #d3ddc7;background:white;padding:10px 16px;color:#758869;font-size:15px;margin-left:8px}.post-actions .delete-post{color:#986c56}.admin-reauth-link{font-size:14px;color:#7a8a6c}.detail-state{text-align:center;padding:50px 0 90px}.detail-state h1{font-size:24px;font-weight:400;margin:25px 0}.detail-state p{font-size:16px;color:#839177}.detail-error-mark{font:italic 60px Georgia,serif;color:#becbb2}.detail-state-actions{display:flex;justify-content:center;align-items:center;gap:25px;margin-top:28px;font-size:15px}.detail-state-actions a{text-decoration:none}.detail-inline-error{font-size:16px;color:#a85e49}.detail-modal-backdrop{position:fixed;inset:0;z-index:2000;display:flex;justify-content:center;align-items:center;padding:16px;background:#1f342088}.detail-modal{width:min(680px,100%);max-height:90vh;overflow:auto;background:white;padding:30px}.detail-modal>header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e2e8da;padding-bottom:15px;margin-bottom:25px}.detail-modal h2{font-weight:400;font-size:23px;color:#425d35}.detail-modal>header>button{border:0;background:transparent;font-size:25px;color:#8b9c7b}@media(max-width:650px){.community-detail{padding:32px 22px 60px}.detail-breadcrumb{margin-bottom:35px;font-size:12px}.community-post-header h1{font-size:24px}.community-post-meta{gap:12px;font-size:13px}.community-post-body{padding:32px 0 45px}.community-post-body>p{font-size:17px}.detail-modal{padding:22px}}
</style>
